document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("gravel-form"),n=document.getElementById("gravel-result");window.setPreset=function(n,t,o){document.getElementById("gravel-length").value=n,document.getElementById("gravel-width").value=t,document.getElementById("gravel-depth").value=o,e.dispatchEvent(new Event("submit"))},function(){const e=document.getElementById("gravel-form");if(e){e.insertAdjacentHTML("beforebegin",'\n      <div class="quick-converter" style="background: #f5f5f5; padding: 15px; margin: 20px 0; border-radius: 8px;">\n        <h4>🔄 Quick Gravel Conversion Calculator</h4>\n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin: 10px 0;">\n          <div>\n            <label>Cubic Yards: <input type="number" id="yards-input" step="0.1" placeholder="Enter cubic yards"></label>\n          </div>\n          <div>\n            <label>Gravel Type: \n              <select id="conversion-type">\n                <option value="1.5">Crushed Stone (1.5 tons/yard)</option>\n                <option value="1.3">Pea Gravel (1.3 tons/yard)</option>\n                <option value="1.2">River Rock (1.2 tons/yard)</option>\n                <option value="1.6">Crusher Run (1.6 tons/yard)</option>\n                <option value="1.4">Decomposed Granite (1.4 tons/yard)</option>\n              </select>\n            </label>\n          </div>\n        </div>\n        <div id="conversion-result" style="margin-top: 10px; font-weight: bold; color: #2c5530;"></div>\n      </div>\n    ');const t=document.getElementById("yards-input"),o=document.getElementById("conversion-type"),r=document.getElementById("conversion-result");function n(){const e=parseFloat(t.value),n=parseFloat(o.value);if(e>0){const t=e*n,o=t*(100/n*1.3);r.innerHTML=`\n            ${e} cubic yards = <strong>${t.toFixed(1)} tons</strong><br>\n            Coverage: ~${o.toFixed(0)} sq ft at 3" deep\n          `}else r.innerHTML=""}t.addEventListener("input",n),o.addEventListener("change",n)}}(),e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("gravel-length").value),o=parseFloat(document.getElementById("gravel-width").value),r=parseFloat(document.getElementById("gravel-depth").value),[s,i]=document.getElementById("gravel-type").value.split(",").map(Number),a=parseFloat(document.getElementById("gravel-project").value),d=parseFloat(document.getElementById("gravel-delivery").value);if(t<=0||o<=0||r<=0)return n.textContent="Please enter valid dimensions.",void 0;const l=t*o,p=r/12,c=l*p/27,g=c*a,u=g*s,v=Math.ceil(2*u)/2,y=Math.ceil(2*g)/2,m=v*i,h=m+d,f=2e3*u/l,x=Math.ceil(v/12),$=.5*l/12/27,b=$*s*i;n.innerHTML=`\n        <div class="result-header" style="background: #2c5530; color: white; padding: 15px; border-radius: 8px 8px 0 0; margin-top: 20px;">\n          <h3 style="margin: 0; color: white;">📊 Your Gravel Calculator Results</h3>\n        </div>\n        \n        <div class="result-content" style="border: 2px solid #2c5530; border-radius: 0 0 8px 8px; padding: 20px;">\n          <div class="result-section">\n            <h4>🏗️ Project Specifications:</h4>\n            <p><strong>Area:</strong> ${t}' × ${o}' = ${l} sq ft</p>\n            <p><strong>Depth:</strong> ${r} inches (${p.toFixed(2)} feet)</p>\n            <p><strong>Base volume:</strong> ${c.toFixed(2)} cubic yards</p>\n            <p><strong>With compaction factor:</strong> ${g.toFixed(2)} cubic yards</p>\n          </div>\n          \n          <div class="result-materials" style="background: #f0f8f0; padding: 15px; margin: 15px 0; border-radius: 5px;">\n            <h4>📦 Material Requirements (ORDER THESE AMOUNTS):</h4>\n            <p><strong>🎯 Order: ${y} cubic yards</strong></p>\n            <p><strong>⚖️ Order: ${v} tons</strong></p>\n            <p><strong>Weight:</strong> ${(2e3*v).toLocaleString()} pounds</p>\n            <p><strong>Density:</strong> ${s} tons per cubic yard</p>\n            <p><strong>Weight per sq ft:</strong> ${f.toFixed(1)} lbs</p>\n          </div>\n          \n          <div class="result-conversions" style="background: #fff8e1; padding: 15px; margin: 15px 0; border-radius: 5px;">\n            <h4>🔄 Cubic Yards to Tons Conversion:</h4>\n            <p><strong>Your project:</strong> ${c.toFixed(1)} yards = ${u.toFixed(1)} tons</p>\n            <p><strong>Conversion rate:</strong> 1 cubic yard = ${s} tons (${document.getElementById("gravel-type").selectedOptions[0].text.split(" (")[0]})</p>\n            <p><strong>Coverage rate:</strong> 1 ton covers ~${(108/(r/3)/s).toFixed(0)} sq ft at ${r}" depth</p>\n          </div>\n          \n          <div class="result-delivery">\n            <h4>🚚 Delivery & Cost Information:</h4>\n            <p><strong>Truck loads needed:</strong> ${x} (12-ton trucks)</p>\n            <p><strong>Material cost:</strong> $${m.toFixed(0)}</p>\n            ${d>0?`<p><strong>Delivery fee:</strong> $${d}</p>`:"<p><strong>Self-pickup:</strong> no delivery fee</p>"}\n            <p style="font-size: 1.2em; font-weight: bold; color: #2c5530;"><strong>💰 Total cost: $${h.toFixed(0)}</strong></p>\n            <p><strong>Cost per sq ft:</strong> $${(h/l).toFixed(2)}</p>\n          </div>\n          \n          <div class="result-installation">\n            <h4>🔧 Installation Guide:</h4>\n            <p><strong>1.</strong> Excavate to ${(r+2).toFixed(0)}" depth (includes base)</p>\n            <p><strong>2.</strong> Install landscape fabric/geotextile</p>\n            <p><strong>3.</strong> Add and compact gravel in 2-3" lifts</p>\n            <p><strong>4.</strong> Final grade with 2% crown for drainage</p>\n            <p><strong>5.</strong> Install edge restraints to contain gravel</p>\n          </div>\n          \n          <div class="result-coverage">\n            <h4>📐 Coverage Comparison:</h4>\n            <p><strong>At ${r}":</strong> covers ${l} sq ft (your project)</p>\n            <p><strong>At 3":</strong> would cover ${(108*g/.25).toFixed(0)} sq ft</p>\n            <p><strong>At 6":</strong> would cover ${(108*g/.5).toFixed(0)} sq ft</p>\n          </div>\n          \n          <div class="result-maintenance">\n            <h4>🔄 Annual Maintenance:</h4>\n            <p><strong>Top-up needed:</strong> ${$.toFixed(2)} cubic yards</p>\n            <p><strong>Top-up weight:</strong> ${($*s).toFixed(1)} tons</p>\n            <p><strong>Annual cost:</strong> $${b.toFixed(0)}</p>\n            <p><strong>Frequency:</strong> ${r>=6?"Every 2-3 years":"Annually"}</p>\n          </div>\n          \n          <div class="result-tools">\n            <h4>🛠️ Tools & Equipment Needed:</h4>\n            <p>🚜 Excavator or shovel (for excavation)</p>\n            <p>🎢 Plate compactor (rent $50-75/day)</p>\n            <p>📐 Level and string line</p>\n            <p>🔧 Rake and hand tools</p>\n            <p>🧤 Safety equipment (gloves, glasses)</p>\n          </div>\n          \n          <div class="result-tips">\n            <h4>💡 Professional Tips:</h4>\n            <p>📏 Verify delivery truck access (12+ ft wide)</p>\n            <p>⏰ Schedule delivery after excavation complete</p>\n            <p>🌦️ Avoid delivery in wet weather</p>\n            <p>📋 Check local permits for driveway work</p>\n            <p>💡 Consider hiring contractor for large projects (${l>1e3?"RECOMMENDED for your project size":"optional for your project size"})</p>\n          </div>\n        </div>\n      `})});